#include <bits/stdc++.h>
#define LL long long
#define FOR_LOOP(i, a, b) for (int i = a; i <= b; i++)
using namespace std;
const int P = 998244353, MOD = 1e9 + 7, B = 1e6;
int mod_wrap(ll d) { return (d % P + P) % P; }
LL total_numbers, count_numbers, sum_arrays[7];
int answer_value;
vector<int> array_list[7];

void generate(int level, LL val) {
    total_numbers++;
    array_list[level].push_back(mod_wrap(total_numbers - val));
    if (level < 6) FOR_LOOP(i, 0, 9) generate(level + 1, val * 10 + i);
}

int compute_value(int id, int f) {
    int pos = lower_bound(array_list[id].begin(), array_list[id].end(), P - f) - array_list[id].begin();
    return ((LL)f * array_list[id].size() + sum_arrays[id] - (LL)P * (array_list[id].size() - pos)) % MOD;
}

void search(int depth, LL v) {
    if (v > total_numbers) return;
    if (depth >= 1) {
        if (v * B > total_numbers / 10 && v * B + B - 1 <= total_numbers) {
            int t = 1;
            FOR_LOOP(i, 0, 6) (answer_value += compute_value(i, mod_wrap(count_numbers - v * t))) %= MOD, t *= 10;
            FOR_LOOP(i, 0, 6) count_numbers += array_list[i].size();
            return;
        }
        answer_value = (answer_value + mod_wrap(++count_numbers - v)) % MOD;
    }
    FOR_LOOP(i, !depth, 9) search(depth + 1, v * 10 + i);
}

int main() {
    LL n_input;
    scanf("%lld", &n_input);
    total_numbers = 0;
    generate(0, 0);
    FOR_LOOP(i, 0, 6) {
        sort(array_list[i].begin(), array_list[i].end());
        for (int j = 0; j < (int)array_list[i].size(); j++) sum_arrays[i] += array_list[i][j];
    }
    count_numbers = 0;
    search(0, 0);
    printf("%d\n", answer_value);
    return 0;
}
